const input = $input.first().json;
const { whatsapp, comprobante_url, comprobante_tipo } = input;

if (!whatsapp || !comprobante_url || !comprobante_tipo) {
  throw new Error('whatsapp, comprobante_url y comprobante_tipo son requeridos');
}

if (!['image', 'pdf'].includes(comprobante_tipo)) {
  throw new Error('comprobante_tipo debe ser image o pdf');
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
const filename = `comprobante_${timestamp}`;
const folder_path = `Comprobantes Pago/${whatsapp}`;

return [{ json: { whatsapp, comprobante_url, comprobante_tipo, filename, folder_path, timestamp } }];

const tipo = $('Validar entrada').first().json.comprobante_tipo;
const buffer = $input.first().json.data;

if (tipo === 'image') {
  return [{ json: { data: buffer, tipo: 'image' } }];
} else {
  return [{ json: { data: buffer, tipo: 'pdf' } }];
}

