let datosExtraidos = null;
const imagenResult = $('Analizar imagen con GPT-4o').first()?.json;
const pdfResult = $('Analizar PDF con GPT-4o').first()?.json;

if (imagenResult) {
  datosExtraidos = typeof imagenResult.content === 'string' ? JSON.parse(imagenResult.content) : imagenResult;
} else if (pdfResult) {
  datosExtraidos = typeof pdfResult.content === 'string' ? JSON.parse(pdfResult.content) : pdfResult;
}

if (!datosExtraidos) {
  throw new Error('No se pudieron extraer datos del comprobante');
}

return [{ json: datosExtraidos }];

const datos = $input.first().json;
const plataforma = datos.encabezado?.plataforma || '';

if (plataforma.toLowerCase().includes('mercado pago') || plataforma.toLowerCase().includes('mp')) {
  return [{ json: { ...datos, tipo_verificacion: 'mercado_pago' } }];
} else {
  return [{ json: { ...datos, tipo_verificacion: 'manual' } }];
}

const driveResult = $('Subir a Google Drive').first()?.json;
const datos = $('Merge rutas').first().json;

const response = {
  success: true,
  validado: datos.estado_pago === 'VERIFICADO',
  plataforma: datos.encabezado?.plataforma,
  monto: datos.monto,
  fecha_hora: datos.encabezado?.fecha_hora,
  numero_operacion: datos.numero_operacion,
  remitente: datos.remitente,
  destinatario: datos.destinatario,
  url_comprobante: `https://drive.google.com/file/d/${driveResult.id}/view`,
  nombre_archivo: driveResult.name,
  estado: datos.estado_pago,
  mensaje: datos.estado_pago === 'VERIFICADO' ? 'Pago verificado en Mercado Pago ✓' : 'Comprobante registrado, pendiente revisión de Fla'
};

return [{ json: response }];
